    if(screen==='zone-attributes-menu'){this._applyZoneAttributesMenuItem(this.state.zoneAttributesMenuIndex);return this._emit(reason+':zone-attributes');}
    if(screen==='zone-attribute-options-1-8' || screen==='zone-attribute-options-9-16'){this._applyZoneAttributeOptionVisual();return this._emit(reason+':zone-attribute-options');}
    if(screen==='system-times-menu'){this._applySystemTimesMenuItem(this.state.systemTimesMenuIndex);return this._emit(reason+':system-times');}
