    if(screen==='zone-definition-selector'){this._applyZoneDefinitionSelectorVisual(this.state.zoneDefinitionDisplayedCode,false);return this._emit(reason+':zone-definition-selector');}
    if(screen==='zone-labels-menu'){this._applyZoneLabelsMenuItem(this.state.zoneLabelsMenuIndex);return this._emit(reason+':zone-labels');}
    if(screen==='zone-label-select-options'){this._applyZoneLabelSelectOption(this.state.zoneLabelSelectOptionIndex);return this._emit(reason+':zone-label-options');}
    if(screen==='zone-label-word-entry'){this._applyWordEntryVisual();return this._emit(reason+':word-entry');}
    if(screen==='zone-label-ascii-entry'){this._applyAsciiEntryVisual();return this._emit(reason+':ascii-entry');}
    if(screen==='zone-label-entry'){this._applyZoneLabelEditorVisual();return this._emit(reason+':zone-label-entry');}
    if(screen==='brightness-control'){this._updateBrightnessControlVisual();return this._emit(reason+':brightness');}
    if(screen==='contrast-control'){this._updateContrastControlVisual();return this._emit(reason+':contrast');}
    if(screen==='buzzer-control'){this._updateBuzzerControlVisual();return this._emit(reason+':buzzer');}
    if(screen==='time-date-entry'){this._updateTimeDateEntryVisual();return this._emit(reason+':time-date');}
    if(screen==='access-code-prompt'){var af=this._currentAccessFlow()||{};this._applyMenuVisual(af.prompt||this.config.accessCodePrompt||{});return this._emit(reason+':access-prompt');}
