  NeoPanelSimulator.prototype._deleteZoneLabelCharacter=function(){
    if(this.state.screen!=='zone-label-entry') return this.getSnapshot();
    this._clearUiTimer();
    this._clearZoneLabelPendingEntry(false);
    var repeatZero=Number(this.state.zoneLabelZeroDeleteGuardIndex)>=0;
    /* [0] is a continuous delete sequence in Zone Label text entry. The first
       press clears the currently underlined character without moving. Each
       consecutive [0] press then moves one editable position forward and
       clears that position. The editable 2 x 14 cursor wraps from Line 2
       character 14 back to Line 1 character 1. Any other label-entry key
       resets zoneLabelZeroDeleteGuardIndex, so the next [0] starts a new
       sequence at the current underline. */
    if(repeatZero) this.state.zoneLabelCursorIndex=moveZoneLabelPhysicalCursor(this.state.zoneLabelCursorIndex,1);
    var codes=(this.state.zoneLabelEditCodes || []).slice(0,32);
    while(codes.length<32) codes.push(32);
    codes[this.state.zoneLabelCursorIndex]=32;
    this.state.zoneLabelEditCodes=codes;
    this.state.zoneLabelZeroDeleteGuardIndex=this.state.zoneLabelCursorIndex;
    this._applyZoneLabelEditorVisual();
    this._armZoneLabelEntryTimer('zone-label-entry-zero-delete-reminder');
    return this._emit(repeatZero?'zone-label-zero-delete-next':'zone-label-zero-delete-current');
  };
