    this.state.zoneLabelZeroDeleteGuardIndex=-1;
    var samePending=this.state.zoneLabelPendingKey===String(key) && this.state.zoneLabelPendingPressIndex>=0;
    if(!samePending){
      if(this.state.zoneLabelPendingKey || this.state.zoneLabelAdvanceBeforeNextEntry) this.state.zoneLabelCursorIndex=moveZoneLabelPhysicalCursor(this.state.zoneLabelCursorIndex,1);
      this.state.zoneLabelPendingKey=String(key);
      this.state.zoneLabelPendingPressIndex=0;
      this.state.zoneLabelAdvanceBeforeNextEntry=false;
    }else this.state.zoneLabelPendingPressIndex=(this.state.zoneLabelPendingPressIndex+1)%characters.length;
    var character=characters[this.state.zoneLabelPendingPressIndex];
    if(this.state.zoneLabelCase==='lower' && /^[A-Z]$/.test(character)) character=character.toLowerCase();
    var codes=(this.state.zoneLabelEditCodes || []).slice(0,32); while(codes.length<32) codes.push(32);
    codes[this.state.zoneLabelCursorIndex]=keypadAsciiCodeForCharacter(character);
    this.state.zoneLabelEditCodes=codes;
