      if(key==='#')return this._cancelPgmDefinitionAndReturn('pgm-definition-pound-cancel-target');
      if(key==='<')return this.scrollPgmDefinitionSelector(-1);
      if(key==='>')return this.scrollPgmDefinitionSelector(1);
      if(key==='*')return this._pressPgmDefinitionStar();
      if(/^\d$/.test(key))return this._enterPgmDefinitionDigit(key);
      this._armPgmDefinitionsTimeout();return this._emit('pgm-definition-key-ignored:'+key);
