  NeoPanelSimulator.prototype.setDisplay=function(line1,line2){
    if(!this.state.powered) return this.getSnapshot();
    this._clearBootTimer();
    this._clearUiTimer();
    this.state.phase='main';
    this.state.screen='custom';
    this.state.interactive=true;
    this._resetNavigation();
    this.state.display={line1:fit16(line1),line2:fit16(line2)};
    return this._emit('display');
  };
  NeoPanelSimulator.prototype.setBacklight=function(name,on){
    if(!Object.prototype.hasOwnProperty.call(this.state.backlights,name)) throw new Error('Unknown backlight: '+name);
    if(this.state.phase==='boot') this._clearBootTimer();
    this.state.backlights[name]=bool(on);
    return this._emit('backlight:'+name);
  };
  NeoPanelSimulator.prototype.setIndicator=function(name,on){
    if(!Object.prototype.hasOwnProperty.call(this.state.indicators,name)) throw new Error('Unknown indicator: '+name);
    if(this.state.phase==='boot') this._clearBootTimer();
    var mode=normalizeIndicatorMode(on);
    this.state.indicatorModes=this.state.indicatorModes || {ready:'off',armed:'off',trouble:'off',ac:'off'};
    this.state.indicatorModes[name]=mode;
    this.state.indicators[name]=mode!=='off';
    return this._emit('indicator:'+name);
  };
  NeoPanelSimulator.prototype.addModule=function(module){
    module=merge({id:'module-'+Date.now().toString(36),category:'Module',model:'',label:'New module',address:null,connected:true},module || {});
    if(this.state.modules.some(function(item){return item.id===module.id;})) throw new Error('Module id already exists: '+module.id);
    this.state.modules.push(module);
    this.config.modules=clone(this.state.modules);
    return this._emit('module-added:'+module.id);
  };
  NeoPanelSimulator.prototype.updateModule=function(id,changes){
    var index=this.state.modules.findIndex(function(item){return item.id===id;});
    if(index<0) throw new Error('Unknown module: '+id);
    this.state.modules[index]=merge(this.state.modules[index],changes || {});
    this.config.modules=clone(this.state.modules);
    return this._emit('module-updated:'+id);
  };
  NeoPanelSimulator.prototype.removeModule=function(id){
    var before=this.state.modules.length;
    this.state.modules=this.state.modules.filter(function(item){return item.id!==id;});
    if(this.state.modules.length===before) throw new Error('Unknown module: '+id);
    this.config.modules=clone(this.state.modules);
    return this._emit('module-removed:'+id);
  };
